// === Tab: mySketch ===
//
// p5.js Shader Tessellation with OPC UI + Spiral Tiling Effects + Zoom Feature
// -----------------------------------------------------------------------------
// 1) Rotation offset slider is smooth (step = 0.001).
// 2) Pattern fills entire canvas.
// 3) New features: Spiral tiling (swirl transformation) added.
// 4) UI now includes extra controls for spiral arms and mix factor.
// 5) Added zoom in/out using mouse wheel (only when mouse is not over the UI area).

let myShader;
let zoomFactor = 2.0; // More zoomed in by default

function preload() {
  // Create the shader from embedded vertex and fragment shader strings.
  myShader = createShader(vertShader, fragShader);
}

function setup() {
  pixelDensity(1); // Ensures 1:1 mapping between gl_FragCoord and the canvas
  createCanvas(windowWidth, windowHeight, WEBGL);
  noStroke();

  // OPC UI controls with updated default settings.
  OPC.slider('petalSize', 10, 10, 150, 1);
  OPC.slider('rotationOffset', 0, 0, TWO_PI, 0.001);
  OPC.slider('edgeSoftness', 19.90, 0, 20, 0.1);
  OPC.color('color1', "#FFFFFF");
  OPC.color('color2', "#9D24FF");
  OPC.color('color3', "#8052FF");
  OPC.color('bgColor', "#000000");
  // New OPC controls for spiral tiling with updated defaults.
  OPC.slider('spiralArms', 3, 1, 12, 1);
  OPC.slider('spiralMix', 0.99, 0, 1, 0.01);
}

function draw() {
  // Activate the shader on the main canvas each frame.
  shader(myShader);

  // Update shader uniforms from OPC global variables.
  myShader.setUniform("uResolution", [width, height]);
  myShader.setUniform("uPetalSize", petalSize);
  myShader.setUniform("uRotationOffset", rotationOffset);
  myShader.setUniform("uEdgeSoftness", edgeSoftness);
  myShader.setUniform("uColor1", hexToRgb(color1));
  myShader.setUniform("uColor2", hexToRgb(color2));
  myShader.setUniform("uColor3", hexToRgb(color3));
  myShader.setUniform("uBgColor", hexToRgb(bgColor));
  // New uniforms for spiral tiling.
  myShader.setUniform("uSpiralArms", spiralArms);
  myShader.setUniform("uSpiralMix", spiralMix);

  // Set zoom uniform.
  myShader.setUniform("uZoom", zoomFactor);

  // Draw a full-screen quad in CLIP SPACE.
  beginShape(TRIANGLES);
    // 1st triangle.
    vertex(-1, -1, 0);
    vertex( 1, -1, 0);
    vertex( 1,  1, 0);
    // 2nd triangle.
    vertex(-1, -1, 0);
    vertex( 1,  1, 0);
    vertex(-1,  1, 0);
  endShape();
}

// Convert a hex color string to normalized RGB.
function hexToRgb(hex) {
  hex = hex.replace("#", "");
  let bigint = parseInt(hex, 16);
  let r = ((bigint >> 16) & 255) / 255;
  let g = ((bigint >> 8) & 255) / 255;
  let b = (bigint & 255) / 255;
  return [r, g, b];
}

// Keep the canvas responsive.
function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

// Implement mouse wheel zoom feature.
// Zoom only if the mouse is NOT over the UI menu area (assumed here as the top 100px).
function mouseWheel(event) {
  if ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < 100) {
    // If the mouse is in the UI area, do not apply zoom.
    return;
  }

  // Use an exponential factor so that a negative delta (scroll up) zooms in,
  // and a positive delta (scroll down) zooms out.
  zoomFactor *= Math.exp(-event.delta * 0.001);
  zoomFactor = constrain(zoomFactor, 0.1, 10);

  return false; // Prevent default scrolling behavior.
}

// ================== Vertex Shader ==================
const vertShader = `
  precision mediump float;

  attribute vec3 aPosition;
  // Even though we don't use texture coords in the fragment shader,
  // p5 still expects them as default attributes for a WEBGL geometry.
  attribute vec2 aTexCoord;
  varying vec2 vTexCoord;

  void main() {
    vTexCoord = aTexCoord;
    // Position in clip space.
    gl_Position = vec4(aPosition, 1.0);
  }
`;

// ================== Fragment Shader ==================
const fragShader = `
  precision mediump float;
  #define PI 3.1415926535897932384626433832795

  uniform vec2 uResolution;
  uniform float uPetalSize;
  uniform float uRotationOffset;
  uniform float uEdgeSoftness;
  uniform vec3 uColor1;
  uniform vec3 uColor2;
  uniform vec3 uColor3;
  uniform vec3 uBgColor;
  // New uniforms for spiral tiling.
  uniform float uSpiralArms;
  uniform float uSpiralMix;
  // Uniform for zoom.
  uniform float uZoom;

  // vTexCoord is declared but not used.
  varying vec2 vTexCoord;

  // Returns the petal boundary radius given an angular deviation 'delta'.
  float petalBoundary(float delta, float petalSize) {
    float r2 = petalSize * 1.5;
    float r1 = petalSize;
    float a_coef = (r1 - r2) / ((PI / 6.0) * (PI / 6.0));
    return a_coef * delta * delta + r2;
  }

  // Spiral transformation for tiling and recursive effects.
  // pos: local position relative to the grid cell center.
  // swirlFactor: uses uRotationOffset to control the swirl.
  // arms: number of spiral arms.
  vec2 spiralTransform(vec2 pos, float swirlFactor, float arms) {
    float r = length(pos);
    float theta = atan(pos.y, pos.x);
    // Apply a swirl: theta offset is proportional to r and swirlFactor.
    theta += swirlFactor * r * 0.01;
    // Multiply theta by arms and wrap it (creates repeating spiral arms).
    theta = mod(theta * arms, 2.0 * PI);
    return vec2(r * cos(theta), r * sin(theta));
  }

  void main() {
    // Apply zoom: adjust the pixel coordinate about the canvas center.
    vec2 center = uResolution * 0.5;
    vec2 uv = (gl_FragCoord.xy - center) / uZoom + center;

    // Compute a staggered hex grid cell center (original tessellation logic).
    float spacingX = uPetalSize * 2.0;
    float spacingY = uPetalSize * sqrt(3.0);
    vec2 bestCenter = vec2(0.0);
    float bestDist = 1e9;
    float rowCandidate = floor(uv.y / spacingY + 0.5);
    for (int dy = -1; dy <= 1; dy++) {
      float row = rowCandidate + float(dy);
      float xOffset = (mod(row, 2.0) < 0.5) ? 0.0 : spacingX / 2.0;
      float colCandidate = floor((uv.x - xOffset) / spacingX + 0.5);
      for (int dx = -1; dx <= 1; dx++) {
        float col = colCandidate + float(dx);
        vec2 centerCell = vec2(col * spacingX + xOffset, row * spacingY);
        float d = distance(uv, centerCell);
        if (d < bestDist) {
          bestDist = d;
          bestCenter = centerCell;
        }
      }
    }

    // Local position relative to the grid cell center.
    vec2 localP = uv - bestCenter;

    // Apply the spiral transformation.
    vec2 spiralP = spiralTransform(localP, uRotationOffset, uSpiralArms);

    // Mix the original tessellated coordinate with the spiral-transformed coordinate.
    vec2 finalP = mix(localP, spiralP, uSpiralMix);

    // Convert finalP to polar coordinates for the petal boundary calculation.
    float r = length(finalP);
    float theta = atan(finalP.y, finalP.x);
    float fullAngle = (theta < 0.0) ? theta + 2.0 * PI : theta;

    // Determine which wedge (6 total) we are in.
    float wedgeIndexF = mod(floor((fullAngle + PI / 6.0) / (PI / 3.0)), 6.0);
    float wedge = PI / 3.0;
    float a = mod(theta, wedge);
    float delta = abs(a - wedge / 2.0);

    // Compute the radial boundary for the petal.
    float boundary = petalBoundary(delta, uPetalSize);

    // Smooth step for anti-aliasing at the petal edge.
    float t = smoothstep(boundary, boundary - uEdgeSoftness, r);

    // Cycle through three colors based on the wedge index.
    float modIndex = mod(wedgeIndexF, 3.0);
    vec3 petalColor;
    if (modIndex < 0.5) {
      petalColor = uColor1;
    } else if (modIndex < 1.5) {
      petalColor = uColor2;
    } else {
      petalColor = uColor3;
    }

    // Blend the petal color with the background based on the smooth edge.
    vec3 finalColor = mix(petalColor, uBgColor, t);
    gl_FragColor = vec4(finalColor, 1.0);
  }
`;

